# AuraSound Auto-Patcher Script (Explore Trending + 1s Instant Preview + Mobile Responsive + Background Queue)
$ErrorActionPreference = "Stop"
Write-Host "=== Dang cap nhat AuraSound (Explore Trending + Instant Preview + Mobile Responsive) ===" -ForegroundColor Cyan
$files = @{}
$files["src/app/api/tracks/ingest/route.ts"] = ""
$files["src/app/api/tracks/trending/route.ts"] = ""
$files["src/app/api/tracks/stream/route.ts"] = ""
$files["src/app/api/tracks/search/route.ts"] = ""
$files["src/app/api/tracks/delete/route.ts"] = ""
$files["src/components/modals/SmartIngestModal.tsx"] = ""
$files["src/components/player/YouTubePreviewBridge.tsx"] = ""
$files["src/store/usePlayerStore.ts"] = ""
$files["src/core/types/audio.ts"] = ""
$files["src/core/audio/AudioEngine.ts"] = ""
$files["src/hooks/useAudioPlayer.ts"] = ""
$files["src/components/player/FloatingPlayerBar.tsx"] = ""
$files["src/app/(desktop)/explore/page.tsx"] = ""
$files["src/app/(desktop)/page.tsx"] = ""
$files[".github/workflows/ingest.yml"] = ""
foreach ($relPath in $files.Keys) {
    $fullPath = Join-Path (Get-Location) $relPath
    $dir = Split-Path $fullPath -Parent
    if (!(Test-Path $dir)) { New-Item -ItemType Directory -Force -Path $dir | Out-Null }
    $bytes = [System.Convert]::FromBase64String($files[$relPath])
    [System.IO.File]::WriteAllBytes($fullPath, $bytes)
    Write-Host "  [OK] Da cap nhat: $relPath" -ForegroundColor Green
}

# Tu dong bo sung responsive hidden md:flex cho SidebarNav.tsx (neu co)
$sidebarPath = Join-Path (Get-Location) "src/components/layout/SidebarNav.tsx"
if (Test-Path $sidebarPath) {
    $sbContent = [System.IO.File]::ReadAllText($sidebarPath, [System.Text.Encoding]::UTF8)
    if ($sbContent -notmatch "hidden md:flex") {
        $sbUpdated = $sbContent -replace "flex flex-col", "hidden md:flex flex-col"
        if ($sbUpdated -ne $sbContent) {
            [System.IO.File]::WriteAllText($sidebarPath, $sbUpdated, [System.Text.Encoding]::UTF8)
            Write-Host "  [OK] Da cap nhat responsive hidden md:flex cho: src/components/layout/SidebarNav.tsx" -ForegroundColor Green
        }
    }
}

Write-Host "=== Hoan tat cap nhat 15 file! Hay chay: npx tsc --noEmit ===" -ForegroundColor Cyan
